"use client"

import { Pencil, Save, Undo2 } from "lucide-react"
import * as React from "react"
import { useMemo, useState } from "react"
import ReactMarkdown from "react-markdown"

import {
  MessageArtifact,
  MessageCode,
  MessageReasoning,
  MessageToolCall,
  type MessageArtifactData,
  type MessageCodeBlockData,
  type MessageToolCallData,
} from "@/components/ui/message-parts"
import { cn } from "@/lib/utils"

export type PatternHandler = {
  pattern: RegExp
  render: (match: RegExpExecArray) => React.ReactNode
}

export type ActionButton = {
  id: string
  icon: React.ReactNode
  onClick: () => void
  title?: string
  className?: string
  position?: "inside" | "outside"
}

export type MessageProps = {
  content: string
  sender: "user" | "assistant"
  actionButtons?: ActionButton[]
  editable?: boolean
  onEdit?: (content: string) => void
  patternHandlers?: PatternHandler[]
  className?: string
  contentClassName?: string
  /** Explicit reasoning (overrides `<think>` parse when set). */
  reasoning?: string | null
  reasoningDefaultOpen?: boolean
  tools?: MessageToolCallData[]
  codeBlocks?: MessageCodeBlockData[]
  artifacts?: MessageArtifactData[]
}

const THINK_TAG_REGEX = /<think>([\s\S]*?)<\/think>/i
const USER_PREVIEW_MAX_WORDS = 80

function previewUserMessageText(text: string, maxWords: number) {
  const words = text.trim().split(/\s+/)
  if (words.length <= maxWords) {
    return { preview: text, remainder: "" }
  }
  return {
    preview: words.slice(0, maxWords).join(" ") + "…",
    remainder: words.slice(maxWords).join(" "),
  }
}

export function Message({
  content,
  sender,
  actionButtons = [],
  editable = false,
  onEdit,
  patternHandlers = [],
  className,
  contentClassName,
  reasoning: reasoningProp,
  reasoningDefaultOpen = false,
  tools = [],
  codeBlocks = [],
  artifacts = [],
}: MessageProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editedContent, setEditedContent] = useState(content)
  const [longPromptExpanded, setLongPromptExpanded] = useState(false)

  const { reasoning, displayContent } = useMemo(() => {
    if (reasoningProp != null) {
      return { reasoning: reasoningProp || null, displayContent: content }
    }
    const match = THINK_TAG_REGEX.exec(content)
    if (!match) return { reasoning: null, displayContent: content }
    return {
      reasoning: match[1].trim(),
      displayContent: content.replace(THINK_TAG_REGEX, "").trim(),
    }
  }, [content, reasoningProp])

  React.useEffect(() => {
    setEditedContent(content)
  }, [content])

  const processContent = React.useCallback(
    (text: string): React.ReactNode => {
      if (!text || patternHandlers.length === 0) return text
      const segments: React.ReactNode[] = []
      let cursor = 0
      while (cursor < text.length) {
        let earliest: {
          handler: PatternHandler
          match: RegExpExecArray
          index: number
        } | null = null
        for (const handler of patternHandlers) {
          handler.pattern.lastIndex = cursor
          const match = handler.pattern.exec(text)
          if (match && (!earliest || match.index < earliest.index)) {
            earliest = { handler, match, index: match.index }
          }
        }
        if (!earliest) {
          segments.push(text.slice(cursor))
          break
        }
        if (earliest.index > cursor) {
          segments.push(text.slice(cursor, earliest.index))
        }
        let rendered: React.ReactNode
        try {
          rendered = earliest.handler.render(earliest.match) ?? earliest.match[0]
        } catch {
          rendered = earliest.match[0]
        }
        segments.push(
          <React.Fragment key={`${earliest.index}-${cursor}`}>
            {rendered}
          </React.Fragment>
        )
        cursor = earliest.index + earliest.match[0].length
      }
      return <>{segments}</>
    },
    [patternHandlers]
  )

  const markdownComponents = useMemo(() => {
    if (patternHandlers.length === 0) return undefined
    const processChildren = (children: React.ReactNode) => {
      if (Array.isArray(children)) {
        return children.map((c, index) =>
          typeof c === "string" ? (
            <React.Fragment key={index}>{processContent(c)}</React.Fragment>
          ) : (
            <React.Fragment key={index}>{c}</React.Fragment>
          )
        )
      }
      return typeof children === "string" ? processContent(children) : children
    }
    return {
      p: ({ children }: { children?: React.ReactNode }) => (
        <p className="mb-3 last:mb-0">{processChildren(children)}</p>
      ),
      li: ({ children }: { children?: React.ReactNode }) => (
        <li>{processChildren(children)}</li>
      ),
    }
  }, [patternHandlers, processContent])

  const { insideButtons, outsideButtons } = useMemo(() => {
    const inside = actionButtons.filter((btn) => btn.position !== "outside")
    const outside = actionButtons.filter((btn) => btn.position === "outside")
    return { insideButtons: inside, outsideButtons: outside }
  }, [actionButtons])

  const handleSaveEdit = () => {
    setIsEditing(false)
    if (onEdit && editedContent !== content) onEdit(editedContent)
  }

  if (sender === "user") {
    if (isEditing) {
      return (
        <div
          className={cn("mb-4 flex w-full justify-end", className)}
        >
          <div className="w-full max-w-[70%] rounded-[18px] border border-border bg-muted px-4 py-2.5">
            <textarea
              value={editedContent}
              onChange={(e) => setEditedContent(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
                  handleSaveEdit()
                } else if (e.key === "Escape") {
                  setIsEditing(false)
                  setEditedContent(content)
                }
              }}
              rows={3}
              autoFocus
              className="w-full resize-none border-0 bg-transparent text-[15px] text-foreground outline-none"
            />
            <div className="mt-2 flex justify-end gap-1">
              <button
                type="button"
                title="Cancel"
                onClick={() => {
                  setIsEditing(false)
                  setEditedContent(content)
                }}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-background hover:text-foreground"
              >
                <Undo2 className="h-3.5 w-3.5" />
              </button>
              <button
                type="button"
                title="Save"
                onClick={handleSaveEdit}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-primary hover:bg-background"
              >
                <Save className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>
        </div>
      )
    }

    const { preview, remainder } = previewUserMessageText(
      displayContent,
      USER_PREVIEW_MAX_WORDS
    )

    return (
      <div
        className={cn(
          "group mb-4 flex min-w-0 w-full items-center justify-end gap-1",
          className
        )}
      >
        {editable && onEdit && (
          <button
            type="button"
            title="Edit message"
            onClick={() => setIsEditing(true)}
            className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground opacity-0 transition hover:bg-muted hover:text-foreground group-hover:opacity-100"
          >
            <Pencil className="h-3.5 w-3.5" />
          </button>
        )}
        <div
          className={cn(
            "max-w-[70%] min-w-0 rounded-[18px] px-4 py-2.5 text-[15px] leading-relaxed break-words whitespace-pre-wrap text-foreground",
            contentClassName
          )}
          style={{ background: "var(--user-bubble)" }}
        >
          {remainder && !longPromptExpanded ? preview : displayContent}
          {remainder ? (
            <button
              type="button"
              className="mt-2 block w-full rounded-md py-1 text-left text-[13px] font-medium text-primary underline-offset-2 hover:underline"
              aria-expanded={longPromptExpanded}
              onClick={() => setLongPromptExpanded((v) => !v)}
            >
              {longPromptExpanded ? "Show less" : "Show more"}
            </button>
          ) : null}
        </div>
      </div>
    )
  }

  return (
    <div className={cn("group mb-4", className)}>
      <div
        className={cn(
          "max-w-full text-[15px] leading-relaxed text-foreground",
          contentClassName
        )}
      >
        {reasoning ? (
          <MessageReasoning defaultOpen={reasoningDefaultOpen}>
            {reasoning}
          </MessageReasoning>
        ) : null}

        {tools.length > 0 ? (
          <div className="mb-3 space-y-0">
            {tools.map((tool) => (
              <MessageToolCall key={tool.id} tool={tool} />
            ))}
          </div>
        ) : null}

        {displayContent ? (
          <div className="prose prose-neutral dark:prose-invert max-w-none prose-p:my-3 prose-headings:mb-2 prose-headings:mt-4 prose-pre:rounded-lg">
            <ReactMarkdown components={markdownComponents}>
              {displayContent}
            </ReactMarkdown>
          </div>
        ) : null}

        {codeBlocks.map((block, i) => (
          <MessageCode key={`${block.language ?? "code"}-${i}`} block={block} />
        ))}

        {artifacts.map((artifact) => (
          <MessageArtifact key={artifact.id} artifact={artifact} />
        ))}

        {(insideButtons.length > 0 ||
          outsideButtons.length > 0 ||
          (editable && onEdit)) && (
          <div className="mt-2 flex flex-wrap items-center gap-1 opacity-0 transition group-hover:opacity-100">
            {[...insideButtons, ...outsideButtons].map((button) => (
              <button
                key={button.id}
                type="button"
                title={button.title}
                onClick={button.onClick}
                className={cn(
                  "inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground",
                  button.className
                )}
              >
                {button.icon}
              </button>
            ))}
            {editable && onEdit && (
              <button
                type="button"
                title="Edit message"
                onClick={() => setIsEditing(true)}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <Pencil className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

export type {
  MessageArtifactData,
  MessageCodeBlockData,
  MessageToolCallData,
} from "@/components/ui/message-parts"
export {
  MessageArtifact,
  MessageCode,
  MessageReasoning,
  MessageToolCall,
} from "@/components/ui/message-parts"

"use client"

import {
  Check,
  ChevronDown,
  Copy,
  FileText,
  Table2,
  Wrench,
  XCircle,
  Clock,
  CheckCircle2,
} from "lucide-react"
import { useState, type ReactNode } from "react"
import ReactMarkdown from "react-markdown"

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { cn } from "@/lib/utils"

export type MessageToolCallData = {
  id: string
  name: string
  status?: "pending" | "running" | "done" | "error"
  input?: string
  output?: string
}

export type MessageCodeBlockData = {
  language?: string
  code: string
  title?: string
}

export type MessageArtifactData = {
  id: string
  title: string
  kind?: "file" | "table" | "chart" | "text" | string
  summary?: string
  content?: string
  onOpen?: () => void
}

export function MessageReasoning({
  children,
  defaultOpen = false,
  className,
}: {
  children: string
  defaultOpen?: boolean
  className?: string
}) {
  const [open, setOpen] = useState(defaultOpen)
  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("mb-3", className)}
    >
      <CollapsibleTrigger asChild>
        <button
          type="button"
          className="flex items-center gap-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <span
            className="inline-flex h-5 w-5 items-center justify-center rounded-md"
            style={{
              background: "var(--bg-soft)",
              border: "1px solid var(--border)",
            }}
          >
            <ChevronDown
              className={cn(
                "h-3 w-3 transition-transform",
                open && "rotate-180"
              )}
            />
          </span>
          Reasoning
          <span className="text-[11px] text-muted-foreground">
            {open ? "Hide" : "Show"}
          </span>
        </button>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div
          className="mt-2 rounded-lg p-3 text-[13px] leading-relaxed text-muted-foreground prose prose-sm prose-neutral dark:prose-invert max-w-none"
          style={{
            background: "var(--bg-soft)",
            border: "1px solid var(--border)",
          }}
        >
          <ReactMarkdown>{children}</ReactMarkdown>
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

const toolStatusIcon: Record<
  NonNullable<MessageToolCallData["status"]>,
  ReactNode
> = {
  pending: <Clock className="h-3.5 w-3.5 text-muted-foreground" />,
  running: <Clock className="h-3.5 w-3.5 animate-pulse text-primary" />,
  done: <CheckCircle2 className="h-3.5 w-3.5 text-emerald-600" />,
  error: <XCircle className="h-3.5 w-3.5 text-destructive" />,
}

const toolStatusLabel: Record<
  NonNullable<MessageToolCallData["status"]>,
  string
> = {
  pending: "Pending",
  running: "Running",
  done: "Done",
  error: "Error",
}

export function MessageToolCall({
  tool,
  defaultOpen = false,
  className,
}: {
  tool: MessageToolCallData
  defaultOpen?: boolean
  className?: string
}) {
  const [open, setOpen] = useState(defaultOpen)
  const status = tool.status ?? "done"

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("mb-2 overflow-hidden rounded-lg", className)}
      style={{ border: "1px solid var(--border)" }}
    >
      <CollapsibleTrigger asChild>
        <button
          type="button"
          className="flex w-full items-center gap-2 px-3 py-2 text-left text-[13px]"
          style={{ background: "var(--bg-soft)", color: "var(--ink)" }}
        >
          <Wrench className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="min-w-0 flex-1 truncate font-medium">{tool.name}</span>
          <span className="inline-flex items-center gap-1 text-[11px] text-muted-foreground">
            {toolStatusIcon[status]}
            {toolStatusLabel[status]}
          </span>
          <ChevronDown
            className={cn(
              "h-3.5 w-3.5 text-muted-foreground transition-transform",
              open && "rotate-180"
            )}
          />
        </button>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div className="space-y-2 border-t border-border px-3 py-2">
          {tool.input ? (
            <div>
              <div className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                Input
              </div>
              <pre
                className="overflow-x-auto rounded-md p-2 text-[12px] leading-relaxed"
                style={{
                  background: "var(--muted)",
                  color: "var(--ink-2)",
                  fontFamily: "var(--font-mono)",
                }}
              >
                {tool.input}
              </pre>
            </div>
          ) : null}
          {tool.output ? (
            <div>
              <div className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                Output
              </div>
              <pre
                className="overflow-x-auto rounded-md p-2 text-[12px] leading-relaxed"
                style={{
                  background: "var(--muted)",
                  color: "var(--ink-2)",
                  fontFamily: "var(--font-mono)",
                }}
              >
                {tool.output}
              </pre>
            </div>
          ) : null}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

export function MessageCode({
  block,
  className,
}: {
  block: MessageCodeBlockData
  className?: string
}) {
  const [copied, setCopied] = useState(false)
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(block.code)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1200)
    } catch {
      /* ignore */
    }
  }

  return (
    <div
      className={cn("my-3 overflow-hidden rounded-lg", className)}
      style={{ border: "1px solid var(--border)" }}
    >
      <div
        className="flex items-center justify-between gap-2 px-3 py-1.5"
        style={{ background: "var(--bg-soft)" }}
      >
        <span className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
          {block.title ?? block.language ?? "code"}
        </span>
        <button
          type="button"
          onClick={() => void copy()}
          className="inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[11px] text-muted-foreground hover:bg-muted hover:text-foreground"
        >
          {copied ? (
            <Check className="h-3 w-3" />
          ) : (
            <Copy className="h-3 w-3" />
          )}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <pre
        className="overflow-x-auto p-3 text-[13px] leading-relaxed"
        style={{
          background: "var(--muted)",
          color: "var(--ink)",
          fontFamily: "var(--font-mono)",
          margin: 0,
        }}
      >
        <code>{block.code}</code>
      </pre>
    </div>
  )
}

function artifactIcon(kind?: string) {
  if (kind === "table") return <Table2 className="h-4 w-4" />
  return <FileText className="h-4 w-4" />
}

export function MessageArtifact({
  artifact,
  className,
}: {
  artifact: MessageArtifactData
  className?: string
}) {
  return (
    <button
      type="button"
      onClick={artifact.onOpen}
      className={cn(
        "my-3 flex w-full items-start gap-3 rounded-xl p-3 text-left transition",
        className
      )}
      style={{
        background: "var(--bg-soft)",
        border: "1px solid var(--border)",
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.borderColor = "var(--primary)"
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.borderColor = "var(--border)"
      }}
    >
      <div
        className="grid h-9 w-9 flex-shrink-0 place-items-center rounded-lg"
        style={{
          background: "var(--accent-soft)",
          color: "var(--primary)",
          border: "1px solid var(--border)",
        }}
      >
        {artifactIcon(artifact.kind)}
      </div>
      <div className="min-w-0 flex-1">
        <div
          className="truncate text-[13.5px] font-medium"
          style={{ color: "var(--ink)" }}
        >
          {artifact.title}
        </div>
        <div className="mt-0.5 text-[12px] text-muted-foreground">
          {[artifact.kind, artifact.summary].filter(Boolean).join(" · ")}
        </div>
        {artifact.content ? (
          <pre
            className="mt-2 max-h-28 overflow-auto rounded-md p-2 text-[11px] leading-relaxed"
            style={{
              background: "var(--muted)",
              color: "var(--ink-2)",
              fontFamily: "var(--font-mono)",
            }}
          >
            {artifact.content}
          </pre>
        ) : null}
      </div>
    </button>
  )
}
